#include<stdio.h>
int main()
{float h,r,l,s,sq,vq,vz;
float pi=3.141526;
printf("请输入圆半径r，圆柱高h:");
scanf("%f,%f",&r,&h);
l=2*pi*r;
s=r*r*pi;
sq=4*pi*r*r;
vq=3.0/4.0*pi*r*r*r;
vz=pi*r*r*h;
printf("圆周长为：l=%6.2f\n",l);
printf("圆面积为：s=%6.2f\n",s);
printf("圆球表面积为：sq=%6.2f\n",sq);
printf("圆球体积为：vq=%6.2f\n",vq);
printf("圆柱体积为：vz=%6.2f\n",vz);
return 0;
}
该程序的作用是在输入圆半径和圆柱高后计算一系列体积和表面积，所有结果的数据类型都是小数点后两位的浮点型数据。
3.
#include<stdio.h>
#include<math.h>
int main()
{double r5,r3,r2,r1,p,p1,p2,p3,p4,p5;
p=10000;
r5=0.03;r3=0.0275;r2=0.021;r1=0.015;r0=0.0035
p1=p*(1+r5*5);
p2=p*(1+2*r2)(1+3*r3);
p3=p*(1+3*r3)(1+2*r2);
p4=p*pow(1+r1,5);
p5=p*pow(1+r0/4,4*5);
printf("p1=%f\n",p1);
printf("p2=%f\n",p2);
printf("p3=%f\n",p3);
printf("p4=%f\n",p4);
printf("p5=%f\n",p5);
return 0;
}
该程序是计算五种不同储蓄方式最后存款利息,其中pow代表的是连乘。
4.
#include<stdio.h>
int main()
{char c1='C',c2='h',c3='i',c4='n',c5='a';
c1=c1+4;
c2=c2+4;
c3=c3+4;
c4=c4+4;
c5=c5+4;
printf("密码是：%c%c%c%c%c\n",c1,c2,c3,c4,c5);
return 0;
}
该程序是将原来的字母用其后面的四个字母代替，然后输出。用赋值的方法使c1,c2,c3,c4,c5这5个变量的值分别对应China，经过运算，使它们分别变成自己后面第四个字母。
改变c1,c2,c3,c4,c5的初值为：Today，要求W用A代替，X用B代替，Y用C代替，Z用D代替，程序如下：
#include<stdio.h>
int main()
{char c1='T',c2='o',c3='d',c4='a',c5='y';
if(c1>'W'&&c1<='Z'||c1>='w'&&c1<='z')
c1=c1-22;
else
c2=c1+4;
if(c2>'W'&&c2<='Z'||c2>='w'&&c2<='z')
c2=c2-22;
else
c2=c2=4;
if(c3>'W'&&c3<='Z'||c3>='w'&&c3<='z')
c3=c3-22;
else
c3=c3-4;
if(c4>'W'&&c4<='Z'||c4>='w'&&c4<='z')
c4=c4-22;
else
c4=c4-4;
if(c5>'W'&&c5<='Z'||c5>='w'&&c5<='z')
c5=c5-22;
else
c5=c5-4;
printf("密码是：%c%c%c%c%c\n",c1,c2,c3,c4,c5);
return 0;
}
分别检验c1,c2,c3,c4,c5的范围，如果是26个字母中最后四个字母就使其-22，如果不是，就使其+4，最后输出。
将译码规律改为，将一个字母被它前面第四个字母代替，程序修改如下：
#include<stdio.h>
int main()
{char c1='C',c2='h',c3='i',c4='n',c5='a';
c1=c1-4+26;
c2=c2-4;
c3=c3-4;
c4=c4-4;
c5=c5-4+26;
printf("密码是：%c%c%c%c%c\n",c1,c2,c3,c4,c5);
return 0;
}
因为字母C和a的ASCII码减去4的话对应的ASCII码不再是字母，因此要再加上26回到原来的字母表里面。
运行结果
1.

该程序的输出结果程序预期结果一致，将整型数据61和62分别赋值给a和b，将字符型数据a和b赋值给c1和c2，将单精度浮点型数据和双精度浮点型数据分别赋值给d、e、f、g，将长整型数据赋值给p和q。
将程序第10-14行改为：
c1=a,c2=b;
f=3157.890121;g=0.123456789;
d=f;e=g;
p=a=m=50000;q=b=n=-60000;结果如下图所示：

将该程序的10-14行改了之后，就变成将50000和-6000分别都赋值给整型数据a、b、p、q以及长整型数据m、n，由于a、b被定义的是整型数据，c1、c2被定义的是字符型数据，因此如果将a、b直接赋值给c1、c2的话c1、c2就会被随机赋予数据而不是a和b被赋予的数据。
用sizeof检测各类型数据的字节长度的输出结果如下所示：

2.


可以看出，输出的结果都是两位数，与程序中定义的相同并且每个输出结果都有相应的提示。
3.

采用双精度变量，得到的运算结果更准确。
