import android.app.Activity;
import android.content.pm.ActivityInfo;
import android.content.res.Configuration;
import android.os.Bundle;
import android.view.View;
import android.view.View.OnClickListener;
import android.widget.Button;
import android.widget.ImageView;

public class MainActivity extends Activity {
    private Button change = null;    
    private ImageView img = null ;    
    @Override
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);        
        super.setContentView(R.layout.activity_main);  //MAIN附件 
        this.change = (Button) super.findViewById(R.id.change);   
        this.img = (ImageView) super.findViewById(R.id.img) ;  
        this.change.setOnClickListener(new MyOnClickListenerImpl()) ;  
    }
    private class MyOnClickListenerImpl implements OnClickListener {   
        @Override
        public void onClick(View view) {
            if (MainActivity.this.getRequestedOrientation() ==
                    ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED) {    
             MainActivity.this.change.setText("错误：无法改变屏幕方向。") ;
            } else {
                if (MainActivity.this.getRequestedOrientation() ==
                        ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE) { 
                    MainActivity.this.setRequestedOrientation(
                            ActivityInfo.SCREEN_ORIENTATION_PORTRAIT); 
                } else if (MainActivity.this.getRequestedOrientation() ==
                        ActivityInfo.SCREEN_ORIENTATION_PORTRAIT) { 
                    MainActivity.this.setRequestedOrientation(
                            ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);
                }
            }
        }
    }
    @Override
    public void onConfigurationChanged(Configuration newConfig) {  
        if (newConfig.orientation ==
                Configuration.ORIENTATION_LANDSCAPE) {           
            MainActivity.this.change.setText(
                    "改变屏幕方向为竖屏显示（当前为横屏显示）");          
            MainActivity.this.img.setImageResource(
                    R.drawable.ic_launcher_foreground) ; //MLDN附件              
        } else if (newConfig.orientation ==
                Configuration.ORIENTATION_PORTRAIT) {            
            MainActivity.this.change.setText(
                    "改变屏幕方向为横屏显示（当前为竖屏显示）") ;        
            MainActivity.this.img.setImageResource(
                    R.drawable.ic_launcher_background) ; //MLDN附件                 
        }
        super.onConfigurationChanged(newConfig);
    }
}
